--- a/app/billing/proration.ts
+++ b/app/billing/proration.ts
@@ -1,9 +1,9 @@
 // Prorates a plan change over the days left in the billing period.
 export function prorate(oldPriceCents: number, newPriceCents: number, remaining: number, daysInPeriod: number): number {
   if (remaining <= 0) {
-    throw new Error("billing period already ended");
+    return 0;
   }
-  const credit = Math.round((oldPriceCents * remaining) / daysInPeriod);
-  const charge = Math.round((newPriceCents * remaining) / daysInPeriod);
-  return charge - credit;
+  const credit = Math.floor((oldPriceCents * remaining) / daysInPeriod);
+  const charge = Math.ceil((newPriceCents * remaining) / daysInPeriod);
+  return Math.max(charge - credit, 0);
 }
