+import { prorate } from "../../app/billing/proration";
+
+test("a mid-cycle downgrade charges nothing", () => {
+  expect(prorate(3000, 1000, 15, 30)).toBe(0);
+});
+
+test("a change after the period ended charges nothing", () => {
+  expect(prorate(1000, 3000, 0, 30)).toBe(0);
+});

